import{_ as a,c as o,o as t,ag as r}from"./chunks/framework.DZ_cNctr.js";const i="/docs/screenshots/oir-image.webp",f=JSON.parse('{"title":"Olympus OIR Viewer","description":"Free online Olympus OIR viewer: open .oir files from FluoView FV3000 and FV4000 confocals in your browser, with every channel, Z-stack, time series and lambda scan. Large files saved in several parts too. Nothing to install.","frontmatter":{"title":"Olympus OIR Viewer","description":"Free online Olympus OIR viewer: open .oir files from FluoView FV3000 and FV4000 confocals in your browser, with every channel, Z-stack, time series and lambda scan. Large files saved in several parts too. Nothing to install."},"headers":[],"relativePath":"guides/olympus-oir.md","filePath":"guides/olympus-oir.md"}'),n={name:"guides/olympus-oir.md"};function s(l,e,d,h,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="olympus-oir-viewer" tabindex="-1">Olympus OIR Viewer <a class="header-anchor" href="#olympus-oir-viewer" aria-label="Permalink to &quot;Olympus OIR Viewer&quot;">​</a></h1><p>Open the <code>.oir</code> files Olympus and Evident FluoView saves on FV3000 and FV4000 confocal microscopes. Every channel, Z-stack, time series and lambda scan opens as it is. No FluoView, no Fiji, no Bio-Formats export, no upload. OIR files shared on Zenodo open here by their link.</p><p><img src="'+i+'" alt="A tile of a brain section from an FV4000 multi-area scan open in the viewer: two channels in the colours of their FluoView lookup tables, 53 Z planes"></p><h2 id="how-to-open-an-oir-file" tabindex="-1">How to Open an OIR File <a class="header-anchor" href="#how-to-open-an-oir-file" aria-label="Permalink to &quot;How to Open an OIR File&quot;">​</a></h2><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on the viewer, or click <strong>Open Image</strong> and <strong>Choose File</strong>. Once the viewer is installed, a double-click on an <code>.oir</code> file opens it too. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A large image saved in several files</strong>, in any browser. Select <code>name.oir</code> and its other parts together and drop them on the viewer.</li><li><strong>A folder</strong>, in Chrome and Edge. One file opens, several show a list. Use this for a large image saved in several files, and for the folder of a tile scan. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>, or a Zenodo file link that ends in <code>/content</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>Channels</strong> by the names FluoView gave them, such as <code>CH1</code> and <code>CH2</code>, in the colours of their lookup tables.</li><li><strong>Lambda scans</strong> with each wavelength as a channel, named by its wavelength: <code>420 nm</code>, <code>470 nm</code> and on.</li><li><strong>Z and time.</strong> Sliders step through the planes. A Z-stack can also be viewed in 3D. See <a href="./3d-rendering.html">3D Rendering</a>.</li><li><strong>10, 12 and 16-bit data</strong>, with a display range that fits their depth.</li><li><strong>Pixel size, Z step and time interval</strong> from the file. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><p>An OIR stores one resolution. The viewer makes the lower resolutions itself, so a large stitched image zooms out and opens in 3D.</p><p>The viewer was checked against Bio-Formats on sample files from FV3000 and FV4000 microscopes: every plane matched.</p><h2 id="large-images-saved-in-several-files" tabindex="-1">Large Images Saved in Several Files <a class="header-anchor" href="#large-images-saved-in-several-files" aria-label="Permalink to &quot;Large Images Saved in Several Files&quot;">​</a></h2><p>FluoView saves a large acquisition in parts: <code>name.oir</code>, then <code>name_00001</code>, <code>name_00002</code> and on, with no ending. They belong together. Drop them together, open the folder that holds them, or open <code>name.oir</code> by its address with the other parts beside it. The viewer finds the parts by their names.</p><p>A tile scan writes a folder with one <code>.oir</code> per tile, a <code>Map_*.oir</code> and, once stitched, a <code>Stitch_*.oir</code>. Open the folder and pick the stitched image or a tile from the list. <code>Map_*.oir</code> is the map of the scan and holds no image.</p><h2 id="if-a-file-does-not-open" tabindex="-1">If a File Does Not Open <a class="header-anchor" href="#if-a-file-does-not-open" aria-label="Permalink to &quot;If a File Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What you opened</th><th>What the viewer says</th></tr></thead><tbody><tr><td>The first file of a large image, without its other parts</td><td>This image continues in name_00001. Drop both files together, or the folder that holds them.</td></tr><tr><td>An address whose other parts cannot be reached, such as a Dropbox link</td><td>This image continues in name_00001, which this link cannot reach. Download both files and drop their folder on the viewer.</td></tr><tr><td>The <code>Map_*.oir</code> of a tile scan</td><td>It is the map of a tile scan and holds no image. Open one of the tile files beside it, or the stitched image, whose name starts with Stitch.</td></tr><tr><td>An image from a colour camera</td><td>This OIR holds a colour camera image, which the viewer does not open yet.</td></tr><tr><td>A lambda scan of several channels</td><td>This OIR holds a lambda scan of several channels, which the viewer does not open yet.</td></tr></tbody></table><p>Olympus and Evident slide scanners and cellSens save VSI images instead. See the <a href="./olympus-vsi.html">Olympus VSI Viewer</a>.</p><h2 id="public-oir-files-to-try" tabindex="-1">Public OIR Files to Try <a class="header-anchor" href="#public-oir-files-to-try" aria-label="Permalink to &quot;Public OIR Files to Try&quot;">​</a></h2><ul><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F12773657%2Ffiles%2FDAPI_mCherry_4Z_5Lambda-420-630-w10nm-s50nm.oir%2Fcontent" target="_blank" rel="noreferrer">DAPI_mCherry_4Z_5Lambda.oir</a>: a lambda scan of 5 wavelengths and 4 Z planes, FV4000. Nicolas Chiaruttini, <a href="https://zenodo.org/records/12773657" target="_blank" rel="noreferrer">Zenodo 12773657</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F20758452%2Ffiles%2F497_c1_wt_20w_x60.oir%2Fcontent" target="_blank" rel="noreferrer">497_c1_wt_20w_x60.oir</a>: a neuron, one plane, FV3000. Thabault et al., <a href="https://zenodo.org/records/20758452" target="_blank" rel="noreferrer">Zenodo 20758452</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F13680725%2Ffiles%2FStitch_A01_G001.oir%2Fcontent" target="_blank" rel="noreferrer">Stitch_A01_G001.oir</a>: a stitched brain section, 2 channels and 53 Z planes in two files (1.9 GB), FV4000. Nicolas Chiaruttini, <a href="https://zenodo.org/records/13680725" target="_blank" rel="noreferrer">Zenodo 13680725</a>, CC BY 4.0.</li></ul><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a file by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. An OIR keeps its chunk index near its end, so the viewer also asks for the file&#39;s size. The parts of a large image must sit beside the <code>.oir</code> under their own names. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>tiling-sample-brain-section_A01_G001_0001.oir</code>, Nicolas Chiaruttini and Lucie Dixsaut, <a href="https://zenodo.org/records/13680725" target="_blank" rel="noreferrer">Zenodo 13680725</a>, CC BY 4.0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The file is read in your browser. Opening one counts as one opened image of the kind &quot;Olympus OIR file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p>',24)])])}const u=a(n,[["render",s]]);export{f as __pageData,u as default};
